/**
 * Long-form detail for the highest-demand denial codes.
 *
 * The dataset in `denial-codes.ts` ships as one searchable tool page and that
 * remains the primary asset. This file adds genuine depth — a worked example,
 * cross-references and an FAQ block — for the subset of codes that carry real
 * search demand, so those get their own route at /denial-codes/[code].
 *
 * Deliberately NOT all 190. A page per code across the whole dataset would
 * publish ~105 words of unique content each, which is the same thin profile as
 * the state pages Google crawled and declined to index. Only codes with enough
 * substance to stand alone belong here. `generateStaticParams` reads this file,
 * not `denialCodes`, so adding a page means writing the content first.
 */

export type DenialCodeDetail = {
  code: string;
  /**
   * Compact plain-English label for the page title.
   *
   * The official `title` in denial-codes.ts runs to 95 characters, so it
   * cannot drive a title, and without this the title was "CO-97 Denial Code
   * | Vizora" at 26 characters — matching the bare code query and nothing
   * else. Keep under 40 characters so the rendered title lands near 55.
   */
  shortLabel: string;
  /** A concrete scenario showing the denial arising and being resolved. */
  example: string[];
  /** Additional depth beyond the meaning/fix/prevent triple. */
  context: string[];
  /** Other codes commonly seen alongside or confused with this one. */
  relatedCodes: string[];
  /** Glossary slugs. */
  relatedTerms: string[];
  /** Service slugs. */
  relatedServices: string[];
  faqs: { question: string; answer: string }[];
};

